new='''export async function indexIssue(orgId: OrgId, issue: Issue): Promise<void> {
  // Re-read: the caller's copy may predate an archive.
  const current = await issueRepo.findIssueById(orgId, issue.id);
  const project = current
    ? await projectRepo.findProjectById(orgId, current.projectId)
    : null;
  if (!current || current.archivedAt !== null || !project || project.archivedAt !== null) {
    await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "issue",
    current.id,
    [current.title, current.description ?? ""].join("\\n"),
    current.projectId,
  );
}

export async function indexComment(
  orgId: OrgId,
  comment: Comment,
): Promise<void> {
  const current = await commentRepo.findCommentById(orgId, comment.id);
  const issue = current
    ? await issueRepo.findIssueById(orgId, current.issueId)
    : null;
  const project = issue
    ? await projectRepo.findProjectById(orgId, issue.projectId)
    : null;
  if (
    !current ||
    current.archivedAt !== null ||
    !issue ||
    issue.archivedAt !== null ||
    !project ||
    project.archivedAt !== null
  ) {
    await searchRepo.deleteSearchDocument(orgId, "comment", comment.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "comment",
    current.id,
    current.body,
    issue.projectId,
  );
}

export async function indexProject(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  const current = await projectRepo.findProjectById(orgId, project.id);
  if (!current || current.archivedAt !== null) {
    await searchRepo.deleteSearchDocument(orgId, "project", project.id);
    return;
  }
  await searchRepo.upsertSearchDocument(
    orgId,
    "project",
    current.id,
    [current.name, current.description ?? ""].join("\\n"),
    current.id,
  );
}

/** Re-syncs an issue and all of its comments (archived ones get dropped). */
export async function reindexIssueTree(
  orgId: OrgId,
  issue: Issue,
): Promise<void> {
  await indexIssue(orgId, issue);
  let cursor: string | null = null;
  do {
    const page = await commentRepo.listComments({
      orgId,
      issueId: issue.id,
      includeArchived: true,
      limit: 100,
      cursor,
    });
    for (const item of page.items) await indexComment(orgId, item);
    cursor = page.nextCursor;
  } while (cursor);
}

/** Re-syncs a project, its issues and their comments. */
export async function reindexProjectTree(
  orgId: OrgId,
  project: Project,
): Promise<void> {
  await indexProject(orgId, project);
  let cursor: string | null = null;
  do {
    const page = await issueRepo.listIssues({
      orgId,
      projectId: project.id,
      includeArchived: true,
      limit: 100,
      cursor,
    });
    for (const issue of page.items) await reindexIssueTree(orgId, issue);
    cursor = page.nextCursor;
  } while (cursor);
}

